<?php
declare(strict_types=1);

function entity_system_tables():array{return['business_entities','business_entity_relationships','business_entity_company_bindings','business_entity_module_profiles','business_entity_data_authorities','business_entity_access_scopes','business_entity_templates','business_entity_template_applications','integration_connections','integration_entity_bindings','external_id_mappings','integration_sync_runs','integration_events','integration_conflicts','business_entity_events'];}
function entity_system_tables_ready():bool{if(data_is_demo())return true;$pdo=production_database_connection();if(!$pdo)return false;try{$n=entity_system_tables();$s=$pdo->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('.implode(',',array_fill(0,count($n),'?')).')');$s->execute($n);return(int)$s->fetchColumn()===count($n);}catch(Throwable){return false;}}
function entity_system_require_tables():void{if(!entity_system_tables_ready())throw new RuntimeException('Import the Section 24 migration before using Production Data entity or integration writes.');}
function entity_system_demo_collection(string$key,callable$seed):array{if(!isset($_SESSION['gruber_demo_state'][$key]))$_SESSION['gruber_demo_state'][$key]=$seed();return array_values($_SESSION['gruber_demo_state'][$key]);}
function entity_system_demo_save(string$key,array$r,callable$seed):array{$rows=entity_system_demo_collection($key,$seed);$id=(int)($r['id']??0);if($id<=0){$id=max([0,...array_map('intval',array_column($rows,'id'))])+1;$r['id']=$id;$rows[]=$r;}else{$f=false;foreach($rows as$i=>$x)if((int)$x['id']===$id){$rows[$i]=array_replace($x,$r);$r=$rows[$i];$f=true;break;}if(!$f)$rows[]=$r;}$_SESSION['gruber_demo_state'][$key]=array_values($rows);return$r;}
function entity_system_raw_rows(string$table,string$key,callable$seed,string$order='id'):array{if(data_is_demo())return entity_system_demo_collection($key,$seed);if(!entity_system_tables_ready())return[];return production_database_connection()->query("SELECT * FROM {$table} ORDER BY {$order}")->fetchAll();}
function entity_system_effective(array$r):bool{$today=date('Y-m-d');return($r['status']??'active')==='active'&&empty($r['effective_from'])||(($r['status']??'active')==='active'&&(string)$r['effective_from']<=$today&&(empty($r['effective_to'])||(string)$r['effective_to']>=$today));}
function entity_system_visible_entity_ids():array
{
    $entities=entity_system_raw_rows('business_entities','business_entities','entity_system_demo_entities','parent_entity_id,id');
    if(can_use_enterprise_view())return array_map('intval',array_column($entities,'id'));
    $allowed=array_fill_keys(permitted_company_ids(),true);$visible=[];$operating=[];
    foreach($entities as$e){$cid=(int)($e['company_id']??0);if($cid>0&&isset($allowed[$cid])){$visible[(int)$e['id']]=true;$operating[(int)$e['id']]=true;if(!empty($e['parent_entity_id']))$visible[(int)$e['parent_entity_id']]=true;}}
    $relationships=entity_system_raw_rows('business_entity_relationships','business_entity_relationships','entity_system_demo_relationships');
    foreach($relationships as$r){if(!entity_system_effective($r))continue;$from=(int)$r['from_entity_id'];$to=(int)$r['to_entity_id'];if(isset($operating[$to])&&in_array((string)$r['relationship_type'],['provides_service','pays_for','purchases_for','operates','consolidates','owns'],true))$visible[$from]=true;if(isset($operating[$from]))$visible[$to]=true;}
    $authorities=entity_system_raw_rows('business_entity_data_authorities','business_entity_data_authorities','entity_system_demo_authorities');
    foreach($authorities as$a)if(entity_system_effective($a)&&isset($operating[(int)$a['entity_id']]))$visible[(int)$a['authority_entity_id']]=true;
    return array_map('intval',array_keys($visible));
}
function entity_system_entity_visible(array$e):bool{return in_array((int)$e['id'],entity_system_visible_entity_ids(),true);}
function entity_system_filter_entity_rows(array$rows,string$field='entity_id'):array{$visible=array_fill_keys(entity_system_visible_entity_ids(),true);return array_values(array_filter($rows,static fn(array$r):bool=>isset($visible[(int)($r[$field]??0)])));}
