function entity_system_events():array{$rows=entity_system_raw_rows('business_entity_events','business_entity_events','entity_system_demo_events','created_at DESC,id DESC');if(can_use_enterprise_view())return$rows;$visible=array_fill_keys(entity_system_visible_entity_ids(),true);return array_values(array_filter($rows,static fn(array$r):bool=>!empty($r['entity_id'])&&isset($visible[(int)$r['entity_id']])));}
function entity_system_find(array$rows,int$id):?array{foreach($rows as$r)if((int)$r['id']===$id)return$r;return null;}
function entity_system_find_entity(int$id):?array{return entity_system_find(entity_system_entities(),$id);}
