function entity_system_save_row(string$table,string$key,callable$seed,array$r,array$fields):array{entity_system_require_tables();$r['created_at']=$r['created_at']??date('Y-m-d H:i:s');$r['updated_at']=date('Y-m-d H:i:s');if(data_is_demo())return entity_system_demo_save($key,$r,$seed);$pdo=production_database_connection();$id=(int)($r['id']??0);$v=[];foreach($fields as$f){$x=$r[$f]??null;if(is_array($x))$x=json_encode($x,JSON_UNESCAPED_SLASHES);$v[]=$x;}if($id){$v[]=$id;$pdo->prepare('UPDATE '.$table.' SET '.implode(',',array_map(static fn(string$f):string=>$f.'=?',$fields)).',updated_at=NOW() WHERE id=?')->execute($v);}else{$pdo->prepare('INSERT INTO '.$table.' ('.implode(',',$fields).') VALUES ('.implode(',',array_fill(0,count($fields),'?')).')')->execute($v);$id=(int)$pdo->lastInsertId();}$r['id']=$id;return$r;}
