function entity_system_add_event(?int$appId,?int$entityId,string$type,string$entityType,int$recordId,?string$from,?string$to,string$severity,string$note):array{entity_system_require_tables();$r=['id'=>null,'application_id'=>$appId,'entity_id'=>$entityId,'event_type'=>$type,'entity_type'=>$entityType,'entity_record_id'=>$recordId,'from_status'=>$from,'to_status'=>$to,'severity'=>$severity,'evidence_note'=>$note,'created_by'=>(int)current_user()['id'],'created_at'=>date('Y-m-d H:i:s')];if(data_is_demo())return entity_system_demo_save('business_entity_events',$r,'entity_system_demo_events');$p=production_database_connection();$p->prepare('INSERT INTO business_entity_events(application_id,entity_id,event_type,entity_type,entity_record_id,from_status,to_status,severity,evidence_note,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$appId,$entityId,$type,$entityType,$recordId,$from,$to,$severity,$note,$r['created_by']]);$r['id']=(int)$p->lastInsertId();return$r;}
function entity_system_queue_integration_event(int$connectionId,int$entityId,string$direction,string$type,string$recordType,int$recordId,string$key,array$payload,string$note):array{entity_system_require_tables();if(!entity_system_find_entity($entityId))throw new RuntimeException('Integration event entity is outside your permitted scope.');$hash=hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES));foreach(entity_system_integration_events()as$e)if(hash_equals((string)$e['idempotency_key'],$key))return$e;$r=['id'=>null,'connection_id'=>$connectionId,'entity_id'=>$entityId,'direction'=>$direction,'event_type'=>$type,'record_type'=>$recordType,'record_id'=>$recordId,'idempotency_key'=>$key,'payload_checksum'=>$hash,'status'=>'ready','attempt_count'=>0,'occurred_at'=>date('Y-m-d H:i:s'),'processed_at'=>null,'evidence_note'=>$note];if(data_is_demo())return entity_system_demo_save('integration_events',$r,'entity_system_demo_integration_events');$p=production_database_connection();$p->prepare('INSERT INTO integration_events(connection_id,entity_id,direction,event_type,record_type,record_id,idempotency_key,payload_checksum,status,attempt_count,occurred_at,evidence_note) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$connectionId,$entityId,$direction,$type,$recordType,$recordId,$key,$hash,'ready',0,$r['occurred_at'],$note]);$r['id']=(int)$p->lastInsertId();return$r;}
